const crypto = require('crypto');
const secret = $env.INTERNAL_API_SECRET;
const path = '/api/v1/internal/scheduler/due';
const method = 'GET';
const timestamp = Math.floor(Date.now()/1000).toString();
const requestId = crypto.randomUUID();
const canonical = [method, path, timestamp, requestId, ''].join('\n');
const signature = crypto.createHmac('sha256', secret).update(canonical).digest('hex');
return [{ json: { path, headers: { 'X-Signature': signature, 'X-Timestamp': timestamp, 'X-Request-Id': requestId, 'Content-Type': 'application/json' } } }];

